int src_fd, dst_fd; // Assume initialized

struct file_dedupe_range dr = {
    .src_offset = 4096,
    .src_length = 8192,
    .dest_count = 1,
};

// Configure destination 1
dr.info[0].dest_fd = dst_fd;
dr.info[0].dest_offset = 0;

// Execute deduplication
int ret = ioctl(src_fd, FIDEDUPERANGE, &dr);

if (ret == 0) {
    long long shared = dr.info[0].bytes_deduped;
    int status = dr.info[0].status;
    // Check status: FILE_DEDUPE_RANGE_SAME or _DIFFERS
}
